import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../../lib/cn";
import "../../styles/spinner.css";

export interface SpinnerProps extends ComponentPropsWithoutRef<"span"> {
  /** Announced to screen readers while the work is in progress. */
  label?: string;
}

/**
 * Indeterminate loading indicator. Rotates with transform only. With reduced
 * motion, it shows as a static arc.
 */
export function Spinner({ label = "Loading", className, ...props }: SpinnerProps) {
  return (
    <span role="status" className={cn("eui-spinner", className)} {...props}>
      <svg width="1em" height="1em" viewBox="0 0 24 24" fill="none" aria-hidden="true" className="eui-spinner__svg">
        <circle cx="12" cy="12" r="9" stroke="currentColor" strokeOpacity="0.25" strokeWidth="2.5" />
        <path d="M21 12a9 9 0 0 0-9-9" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
      </svg>
      <span className="eui-spinner__label">{label}</span>
    </span>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Spinner. The arc rotates with transform only. */

.eui-spinner {
  display: inline-flex;
  color: currentColor;
  line-height: 0;
}

.eui-spinner__svg {
  animation: eui-spin 0.8s linear infinite;
}

@keyframes eui-spin {
  to {
    transform: rotate(360deg);
  }
}

.eui-spinner__label {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .eui-spinner__svg {
    animation-duration: 2.4s;
  }
}
